{{ config(materialized='incremental', unique_key='HUB_COVERAGE_HK') }}
/* GENERATED by gen_hcon_vault.py -- models are generated.
   HUB_COVERAGE : 7 feed(s) over 7 source view(s), 3 run(s): opus_health_delta3, opus_health_legacy_v4, opus_health_v2
   LOADER SHAPE: ONE loader for this vault table; each run is a SEPARATE feed
   tagged by RECORD_SOURCE and SOURCE_RUN. RECORD_SOURCE is NEVER in the key.
   KEY FORM: md5(upper('HUB_COVERAGE|' || <business key>)), emitted EXPLICITLY -- no macro computes a
   hash in this build. The namespace is a MEASURED collision guard: opus_health_v2 emits
   md5(upper(HUB_ASSESSMENT_BK__SCRUTINY_NO)) AND md5(upper(HUB_PROPOSAL_BK__SCRUTINY_NO)),
   the same column under two hubs, which collide without it; legacy namespaces 1822 of 1822.
   CRITICAL PRECISION: the namespace separates HUBS, NOT REGISTRIES WITHIN A HUB.
   'HUB_POLICY|' prefixes POLICY_REF and POLICY_NO identically, so it does nothing to keep
   two identifier populations inside one hub apart.
   REGISTRY RECONCILIATION, UNRESOLVED: unifying the hash form does NOT establish that the
   two runs' identifier spaces denote the same entities. 6 of the 14 shared hubs have ZERO
   business-key-column overlap between the runs. This hub is ONE KEY SPACE over the
   registries enumerated below; a false merge is unrecoverable after load.
     opus_health_delta3       2 registry/registries: HUB_COVERAGE_BK__COVERAGE, HUB_COVERAGE_BK__COVER_CODE
     opus_health_legacy_v4    3 registry/registries: HUB_COVERAGE_BK__COVER_CODE, HUB_COVERAGE_BK__COVER_SECTION, HUB_COVERAGE_BK__HCP_SEQNO
     opus_health_v2           1 registry/registries: HUB_COVERAGE_BK__CVR_CODE
*/

with feeds as (
    select HUB_COVERAGE_HK, HUB_COVERAGE_BK__HCP_SEQNO as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_coverage__hcp_dt_mem_cov__f855781dde') }}
    union all
    select HUB_COVERAGE_HK, HUB_COVERAGE_BK__CVR_CODE as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_coverage__ctngy_bases_extn__c14824eca8') }}
    union all
    select HUB_COVERAGE_HK, HUB_COVERAGE_BK__COVERAGE as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_coverage__grp_hlt_mem_dtls__b6e4bf35e3') }}
    union all
    select HUB_COVERAGE_HK, HUB_COVERAGE_BK__COVER_CODE as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_coverage__hg_pol_dtls__4a61f25d5e') }}
    union all
    select HUB_COVERAGE_HK, HUB_COVERAGE_BK__COVER_SECTION as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_coverage__hm_doctor_multi_assess__7bd35bc8c3') }}
    union all
    select HUB_COVERAGE_HK, HUB_COVERAGE_BK__COVER_CODE as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_coverage__starpkg_cover_mst__8d9f7e3adc') }}
    union all
    select HUB_COVERAGE_HK, HUB_COVERAGE_BK__COVER_CODE as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_coverage__starpkg_cov_prem_mst__e55f7c4f8a') }}
)

select
    HUB_COVERAGE_HK,
    BUSINESS_KEY,
    min(RECORD_SOURCE) as RECORD_SOURCE,
    min(SOURCE_RUN) as SOURCE_RUN,
    min(LOAD_DATETIME) as LOAD_DATETIME
from feeds
where HUB_COVERAGE_HK is not null
group by HUB_COVERAGE_HK, BUSINESS_KEY
